#!/usr/bin/env python3
# Recreates the "Kadoki Kinomoto" Anki note type (dark-only redesigned mining
# card: frame-image hero, Mincho headword with orange spaced furigana, Jitendex
# structured-glossary rendering; 18 fields = jidoujisho Kinomoto's 17 + Glossary).
#
# Use when the note type is missing from desktop Anki — e.g. after an
# accidental "Download from AnkiWeb" one-way sync wiped local changes
# (which happened 2026-08-30). Refuses to run if the note type exists.
# Requires desktop Anki running with AnkiConnect on 127.0.0.1:8765.
#
# IMPORTANT: adding a note type forces the next sync to be one-way again —
# choose UPLOAD to AnkiWeb, or this note type gets wiped a second time.
#
# Generated 2026-08-30 from the live model via AnkiConnect.
import json, urllib.request

def ac(action, **params):
    r = urllib.request.urlopen(urllib.request.Request('http://127.0.0.1:8765',
        json.dumps({'action': action, 'version': 6, 'params': params}).encode()))
    j = json.load(r)
    if j.get('error'):
        raise Exception(f"{action}: {j['error']}")
    return j['result']

NAME = 'Kadoki Kinomoto'
FIELDS = ['Term', 'Reading', 'Furigana', 'Sentence', 'Cloze Before', 'Cloze Inside', 'Cloze After', 'Meaning', 'Expanded Meaning', 'Collapsed Meaning', 'Notes', 'Context', 'Frequency', 'Pitch Accent', 'Image', 'Term Audio', 'Sentence Audio', 'Glossary']
FRONT = '<div class="k-wrap">\n  {{#Image}}<div class="k-media">{{Image}}</div>{{/Image}}\n  <div class="k-term">{{Term}}</div>\n  <div class="k-sentence">{{#Cloze Inside}}{{Cloze Before}}<span class="cloze">{{Cloze Inside}}</span>{{Cloze After}}{{/Cloze Inside}}{{^Cloze Inside}}{{Sentence}}{{/Cloze Inside}}</div>\n  <div class="k-audio">{{#Term Audio}}{{Term Audio}}{{/Term Audio}}{{#Sentence Audio}}{{Sentence Audio}}{{/Sentence Audio}}</div>\n</div>\n<script src="_kanjax_with_koohii_v3.js"></script>\n<script src="_jquery.bpopup.min.js"></script>'
BACK = '<div class="k-wrap">\n  {{#Image}}<div class="k-media">{{Image}}</div>{{/Image}}\n  <div class="k-term k-back">{{#Furigana}}{{furigana:Furigana}}{{/Furigana}}{{^Furigana}}{{Term}}{{/Furigana}}</div>\n  <div class="k-subline">\n    {{#Pitch Accent}}<span class="k-pitch">{{Pitch Accent}}</span>{{/Pitch Accent}}\n    {{#Reading}}<span class="k-reading">{{Reading}}</span>{{/Reading}}\n    {{#Frequency}}<span class="k-chip">{{Frequency}}</span>{{/Frequency}}\n  </div>\n  <div class="k-audio">{{#Term Audio}}{{Term Audio}}{{/Term Audio}}{{#Sentence Audio}}{{Sentence Audio}}{{/Sentence Audio}}</div>\n  <div class="k-sentence">{{#Cloze Inside}}{{Cloze Before}}<span class="cloze">{{Cloze Inside}}</span>{{Cloze After}}{{/Cloze Inside}}{{^Cloze Inside}}{{Sentence}}{{/Cloze Inside}}</div>\n  {{#Glossary}}<div class="k-gloss">{{Glossary}}</div>{{/Glossary}}\n  {{^Glossary}}{{#Meaning}}<div class="k-meaning">{{Meaning}}</div>{{/Meaning}}{{/Glossary}}\n  {{#Expanded Meaning}}<div class="k-meaning">{{Expanded Meaning}}</div>{{/Expanded Meaning}}\n  {{#Collapsed Meaning}}<details class="k-details"><summary>詳細</summary><div class="k-meaning k-inset">{{Collapsed Meaning}}</div></details>{{/Collapsed Meaning}}\n  {{#Context}}<div class="k-note"><span class="k-label">context</span><span>{{Context}}</span></div>{{/Context}}\n  {{#Notes}}<div class="k-note"><span class="k-label">notes</span><span>{{Notes}}</span></div>{{/Notes}}\n</div>\n<script src="_kanjax_with_koohii v2.js"></script>\n<script src="_jquery.bpopup.min.js"></script>'
CSS = '/* Kadoki Kinomoto — cinematic mining card. DARK ONLY by request:\n   the palette is fixed on .card, so Anki light mode shows the same dark card. */\n.card {\n  --bg: #14161a;\n  --panel: #1d2026;\n  --ink: #ece7dc;\n  --soft: #97917f;\n  --accent: #ff8f74;\n  --accent-soft: rgba(255, 143, 116, .13);\n  --line: rgba(236, 231, 220, .10);\n  --shadow: 0 16px 44px rgba(0, 0, 0, .5);\n  font-family: "Hiragino Sans", "Noto Sans CJK JP", -apple-system, "Helvetica Neue", sans-serif;\n  font-size: 16px;\n  text-align: center;\n  color: var(--ink);\n  background: var(--bg);\n  padding: 16px 8px;\n}\n\n.k-wrap {\n  max-width: 620px;\n  margin: 0 auto;\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 24px;\n  box-shadow: var(--shadow);\n  padding: 20px 22px 26px;\n}\n\n/* video frame / mined image */\n.k-media img {\n  width: 100%;\n  max-height: 46vh;\n  object-fit: contain;\n  border-radius: 14px;\n  box-shadow: 0 8px 26px rgba(0, 0, 0, .28);\n  margin-bottom: 18px;\n}\n\n/* headword */\n.k-term {\n  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", "Noto Serif JP", serif;\n  font-size: 46px;\n  font-weight: 600;\n  letter-spacing: .02em;\n  line-height: 1.5;   /* room for the ruby block — 1.35 crushed the reading into the kanji */\n  margin: 6px 0 4px;\n}\n.k-term.k-back { font-size: 42px; }\n.k-term ruby { ruby-align: center; }\n.k-term ruby rt {\n  font-size: .36em;\n  font-weight: 500;\n  color: var(--accent);\n  letter-spacing: .14em;\n  padding-bottom: .28em;   /* air between the reading and the kanji */\n}\n\n/* reading pill + pitch + frequency */\n.k-subline {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  align-items: center;\n  gap: 10px;\n  margin: 8px 0 2px;\n}\n.k-reading {\n  font-family: "Hiragino Mincho ProN", "Yu Mincho", serif;\n  font-size: 17px;\n  color: var(--accent);\n  background: var(--accent-soft);\n  padding: 3px 14px;\n  border-radius: 999px;\n}\n.k-pitch {\n  font-family: "Hiragino Mincho ProN", "Yu Mincho", serif;\n  font-size: 17px;\n  color: var(--ink);\n}\n.k-chip {\n  font-size: 11.5px;\n  letter-spacing: .12em;\n  text-transform: uppercase;\n  color: var(--soft);\n  border: 1px solid var(--line);\n  padding: 3px 10px;\n  border-radius: 999px;\n}\n\n/* sentence */\n.k-sentence {\n  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", serif;\n  font-size: 21px;\n  line-height: 1.95;\n  margin-top: 14px;\n  text-wrap: balance;\n}\n.k-sentence:empty { display: none; }\n.cloze {\n  color: var(--accent);\n  font-weight: 700;\n  background: var(--accent-soft);\n  border-radius: 6px;\n  padding: 0 4px;\n}\n\n/* meanings */\n.k-meaning {\n  text-align: left;\n  font-size: 15px;\n  line-height: 1.75;\n  color: var(--ink);\n  opacity: .88;\n  margin-top: 16px;\n  padding-top: 14px;\n  border-top: 1px solid var(--line);\n}\n.k-meaning.k-inset { border-top: none; padding-top: 6px; margin-top: 4px; }\n.k-details { margin-top: 12px; text-align: left; }\n.k-details summary {\n  cursor: pointer;\n  color: var(--accent);\n  font-size: 13.5px;\n  letter-spacing: .1em;\n  user-select: none;\n}\n.k-details summary:hover { opacity: .75; }\n\n/* context / notes rows */\n.k-note {\n  display: flex;\n  gap: 10px;\n  align-items: baseline;\n  text-align: left;\n  font-size: 14px;\n  line-height: 1.7;\n  color: var(--soft);\n  margin-top: 10px;\n}\n.k-label {\n  flex-shrink: 0;\n  font-size: 10.5px;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n  color: var(--accent);\n  border: 1px solid var(--accent-soft);\n  background: var(--accent-soft);\n  border-radius: 6px;\n  padding: 2px 7px;\n}\n\n/* audio replay buttons */\n.k-audio { margin-top: 10px; }\n.k-audio .replay-button { margin: 0 6px; }\n.k-audio .replay-button svg { width: 38px; height: 38px; }\n.k-audio .replay-button svg circle { fill: var(--accent-soft); stroke: var(--accent); stroke-width: 2px; }\n.k-audio .replay-button svg path { fill: var(--accent); }\n\n/* pitch-accent marks (same classes the Pitch Accent field emits) */\n.pitch { border-top: solid var(--accent) 2px; padding-top: 1px; }\n.pitch_end {\n  border-color: var(--accent);\n  border-right: solid var(--accent) 2px;\n  border-top: solid var(--accent) 2px;\n  line-height: 1px;\n  margin-right: 1px;\n  padding-right: 1px;\n  padding-top: 1px;\n}\n\n/* ============ Jitendex / Yomitan structured glossary (.k-gloss) ============\n   Same markup the in-app dictionary popup renders (buildGlossaryHtml →\n   .dict-popup-sense blocks + .dict-sc structured content). Rules ported from\n   enhanced-dictionary.js\'s popup stylesheet, re-tinted to the card palette. */\n.k-gloss {\n  text-align: left;\n  margin-top: 16px;\n  padding-top: 14px;\n  border-top: 1px solid var(--line);\n}\n.k-gloss .dict-popup-sense { margin-bottom: 16px; }\n.k-gloss .dict-popup-sense:last-child { margin-bottom: 0; }\n.k-gloss .dict-popup-sense-head {\n  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;\n  margin-bottom: 6px;\n}\n.k-gloss .dict-popup-sense-num { font-size: 1.02em; font-weight: 700; color: var(--ink); margin-right: 4px; }\n.k-gloss .dict-popup-pill {\n  display: inline-block; padding: 2px 8px; border-radius: 5px;\n  font-size: 0.68em; font-weight: 600; letter-spacing: 0.04em; line-height: 1.5;\n}\n.k-gloss .dict-popup-pill-pos { background: rgba(236,231,220,.08); color: var(--soft); }\n.k-gloss .dict-popup-pill-dict { background: var(--accent-soft); color: var(--accent); }\n.k-gloss .dict-popup-glosses {\n  margin: 0; padding-left: 22px; list-style: disc;\n  color: var(--ink); opacity: .9; line-height: 1.5; font-size: 14.5px;\n}\n.k-gloss .dict-popup-glosses li { margin-bottom: 2px; }\n\n.k-gloss .dict-sc { color: var(--ink); opacity: .92; line-height: 1.6; font-size: 14.5px; }\n.k-gloss .dict-sc ol, .k-gloss .dict-sc ul { margin: 3px 0 3px 1.5em; padding: 0; }\n.k-gloss .dict-sc li { margin: 2px 0; }\n.k-gloss .dict-sc ruby rt { font-size: 0.55em; opacity: 0.85; }\n.k-gloss .dict-sc table { border-collapse: collapse; margin: 8px 0; font-size: 0.92em; }\n.k-gloss .dict-sc th, .k-gloss .dict-sc td { border: 1px solid var(--line); padding: 3px 10px; text-align: center; }\n.k-gloss .dict-sc th { background: rgba(236,231,220,.06); font-weight: 600; }\n.k-gloss .dict-sc details { margin: 4px 0; }\n.k-gloss .dict-sc summary { cursor: pointer; color: var(--soft); }\n.k-gloss .dict-sc [data-sc-content="extra-info"],\n.k-gloss .dict-sc [data-sc-content="example-sentence"] {\n  border-left: 2px solid var(--accent); margin: 8px 0; padding: 6px 12px;\n  background: rgba(236,231,220,.04); border-radius: 0 8px 8px 0;\n}\n.k-gloss .dict-sc [data-sc-content="example-sentence-a"] {\n  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif CJK JP", serif;\n  font-size: 1.12em; line-height: 2;\n}\n.k-gloss .dict-sc [data-sc-content="example-sentence-b"] { color: var(--soft); font-size: 0.94em; margin-top: 2px; }\n.k-gloss .dict-sc [data-sc-content="attribution"],\n.k-gloss .dict-sc [data-sc-content="sources"] {\n  color: var(--soft); opacity: .7; font-size: 0.78em; margin-top: 4px; text-align: right;\n}\n.k-gloss .dict-sc-link { color: var(--accent); text-decoration: none; }\n.k-gloss .dict-sc-img { max-width: 100%; vertical-align: middle; box-shadow: none; margin: 0; }\n\n/* Jitendex badges + forms-table marks (dict styles.css conventions) */\n.k-gloss .dict-sc span[data-sc-class="tag"] {\n  border-radius: 0.3em; font-size: 0.78em; font-weight: bold;\n  margin-right: 0.5em; padding: 0.2em 0.4em; vertical-align: text-bottom;\n  word-break: keep-all; background-color: rgba(236,231,220,.14); color: var(--ink);\n}\n.k-gloss .dict-sc td[data-sc-class^="form-"] > span {\n  clip-path: circle(); display: block; font-weight: bold;\n  padding: 0 0.5em; width: fit-content; margin: 0 auto; color: white;\n}\n.k-gloss .dict-sc td[data-sc-class="form-valid"] > span { color: #16181c; background: radial-gradient(#ddd 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-valid"] > span::before { content: "◇"; }\n.k-gloss .dict-sc td[data-sc-class="form-pri"]  > span { background: radial-gradient(green 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-pri"]  > span::before { content: "△"; }\n.k-gloss .dict-sc td[data-sc-class="form-irr"]  > span { background: radial-gradient(crimson 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-irr"]  > span::before { content: "✕"; }\n.k-gloss .dict-sc td[data-sc-class="form-out"]  > span { background: radial-gradient(blue 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-out"]  > span::before { content: "古"; }\n.k-gloss .dict-sc td[data-sc-class="form-old"]  > span { background: radial-gradient(blue 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-old"]  > span::before { content: "旧"; }\n.k-gloss .dict-sc td[data-sc-class="form-rare"] > span { background: radial-gradient(purple 50%, white 100%); }\n.k-gloss .dict-sc td[data-sc-class="form-rare"] > span::before { content: "▽"; }\n.k-gloss .dict-sc span[data-sc-class="form-special"] { color: crimson; }'

if NAME in ac('modelNames'):
    raise SystemExit(NAME + ' already exists — nothing to do')
ac('createModel', modelName=NAME, inOrderFields=FIELDS, css=CSS, isCloze=False,
   cardTemplates=[{'Name': NAME, 'Front': FRONT, 'Back': BACK}])
print('recreated', NAME, 'with', len(ac('modelFieldNames', modelName=NAME)), 'fields')
print('REMINDER: next Anki sync must be UPLOAD to AnkiWeb')
